-- Hand in Hand (2nd Edition), Student Books Starter to 6: every unit and School Link as units for the Bookshelf,
-- each part of a unit as a lesson, typed from the publisher's scope and sequence.
-- Run once in the Supabase SQL Editor after migration-curriculum-catalogue.sql. Safe to re-run: a book that already
-- has units is left alone, so a Hand in Hand book someone made by hand is not touched. Do NOT delete a book's units
-- to reload it once any class has it placed: the delete cascades into every class's pacing, pins and taught history,
-- and orphans the unit links saved in the lesson plans. Correct titles or lessons with UPDATEs instead.
--
-- Units: "Unit 7 · School Subjects", lessons Conversation, Words, Grammar, The World around Us and English Sounds
-- (Books 1 to 4; Books 5 and 6 have no English Sounds; Starter has Sentences in place of Grammar and no World around Us).
-- School Links: "School Link 3 · Different places in a city", lessons for the subject topic and the project, and the
-- Writing Style in Books 5 and 6 (Starter: the comic and the activity). Each lesson's notes hold what the book lists
-- for it; its objective is a draft (source 'claude', not confirmed), so the lesson plans say it is unchecked.

CREATE UNIQUE INDEX IF NOT EXISTS idx_curriculum_books_series_level ON curriculum_books (series_id, lower(level_number));

-- ── Hand in Hand Starter: 18 units, 60 lessons ──
DO $seed$
DECLARE b UUID; u UUID; n INT;
BEGIN
  SELECT bk.id INTO b FROM curriculum_books bk JOIN curriculum_series s ON s.id = bk.series_id WHERE lower(s.name) = 'hand in hand' AND lower(bk.level_number) = lower($q$Starter$q$);
  SELECT count(*) INTO n FROM curriculum_units WHERE book_id = b;
  IF n > 0 THEN
    RAISE NOTICE 'Hand in Hand Starter already has % units; left as it is', n;
  ELSE
