  INSERT INTO curriculum_books (series_id, level_number, title, status) SELECT id, $q$5$q$, '', 'confirmed' FROM curriculum_series WHERE lower(name) = 'hand in hand' ON CONFLICT (series_id, lower(level_number)) DO NOTHING;
    INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 1, $q$Unit 1 · Comparing Animals$q$, $q$Conversation: I'm reading a book about animals. / What's this? / It's a gazelle. It lives in Africa. / Did you know that it's a very fast animal? / No, I didn't. How fast can it run? / It can run up to 97 km/h. / That is fast!
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Conversation$q$, $q$Students will act out the conversation that starts “I'm reading a book about animals.”$q$, $q$I'm reading a book about animals. / What's this? / It's a gazelle. It lives in Africa. / Did you know that it's a very fast animal? / No, I didn't. How fast can it run? / It can run up to 97 km/h. / That is fast!$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$Words$q$, $q$Students will name and use cheetah, deer, fox, giraffe, hippopotamus, rhinoceros, turtle, wolf, slow, fast, light, heavy.$q$, $q$cheetah, deer, fox, giraffe, hippopotamus, rhinoceros, turtle, wolf, slow, fast, light, heavy$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 3, $q$Grammar$q$, $q$Students will ask and answer “Which animal is faster, the deer or the giraffe?” (“The giraffe is faster than the deer.”).$q$, $q$Which animal is faster, the deer or the giraffe? / The giraffe is faster than the deer. / Which animal is the fastest? / The cheetah is the fastest.$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
