    INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 16, $q$Unit 11 · How Much Food$q$, $q$Conversation: I'm getting hungry. / Let's make sandwiches. / I can make peanut butter and jelly sandwiches. / Is there any peanut butter? / Yes, and here's some jelly too. / We have some bread here. / Now we're all set.
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Conversation$q$, $q$Students will act out the conversation that starts “I'm getting hungry.”$q$, $q$I'm getting hungry. / Let's make sandwiches. / I can make peanut butter and jelly sandwiches. / Is there any peanut butter? / Yes, and here's some jelly too. / We have some bread here. / Now we're all set.$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$Words$q$, $q$Students will name and use a lot of: cookies, sandwiches, ice cream, lemonade; a few: potato chips, hot dogs; a little: pizza, fruit.$q$, $q$a lot of: cookies, sandwiches, ice cream, lemonade; a few: potato chips, hot dogs; a little: pizza, fruit$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 3, $q$Grammar$q$, $q$Students will ask and answer “How many sandwiches are there?” (“There are (a lot of”).$q$, $q$How many sandwiches are there? / There are (a lot of / a few) sandwiches. / How much ice cream is there? / There is (a lot of / a little) ice cream. / Are there a lot of cookies? Is there a lot of fruit?$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 4, $q$The World around Us$q$, $q$Students will read “All-Fruit Popsicles” and compare it with their own lives.$q$, $q$All-Fruit Popsicles (Spain)$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
    INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 17, $q$Unit 12 · Five Senses$q$, $q$Conversation: These are new sneakers, aren't they? / Yes. How did you know? / I can see them. They look new. / Your mom is making chili, isn't she? / Yes. How did you know? / I can smell it. It smells good. / It's raining outside, isn't it? / Yes. I can hear it too.
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Conversation$q$, $q$Students will act out the conversation that starts “These are new sneakers, aren't they?”$q$, $q$These are new sneakers, aren't they? / Yes. How did you know? / I can see them. They look new. / Your mom is making chili, isn't she? / Yes. How did you know? / I can smell it. It smells good. / It's raining outside, isn't it? / Yes. I can hear it too.$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
