    INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 1, $q$Unit 1 · Weekend Life$q$, $q$Conversation: How was your weekend? / It was great. We went to the amusement park. / How did you like the new roller coaster? / I was a little scared at first, but it was really exciting. / Did you have a good weekend? / Not really. I had a boring weekend. / I didn't do anything interesting.
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Conversation$q$, $q$Students will act out the conversation that starts “How was your weekend?”$q$, $q$How was your weekend? / It was great. We went to the amusement park. / How did you like the new roller coaster? / I was a little scared at first, but it was really exciting. / Did you have a good weekend? / Not really. I had a boring weekend. / I didn't do anything interesting.$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$Words$q$, $q$Students will name and use eat out at a restaurant, build a model plane, see a musical, sail on a boat, visit grandparents, write emails to friends, go to a water park, have a sleepover.$q$, $q$eat out at a restaurant, build a model plane, see a musical, sail on a boat, visit grandparents, write emails to friends, go to a water park, have a sleepover$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 3, $q$Grammar$q$, $q$Students will ask and answer “What did she do on the weekend?” (“She ate out at a restaurant.”).$q$, $q$What did she do on the weekend? / She ate out at a restaurant. / Did he see a musical on the weekend? / Yes, he did. No, he didn't.$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 4, $q$The World around Us$q$, $q$Students will read “My First Bike Ride” and compare it with their own lives.$q$, $q$My First Bike Ride (Netherlands)$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
    INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 2, $q$Unit 2 · Going on Vacation$q$, $q$Conversation: I've just finished making the hotel reservation. / Our kids don't have passports yet. / You're right. They need to get passport photos. / Let's have their photos taken this afternoon. / What are you doing? / We're making plans for our summer vacation. / Great! I can't wait to see the pyramids.
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Conversation$q$, $q$Students will act out the conversation that starts “I've just finished making the hotel reservation.”$q$, $q$I've just finished making the hotel reservation. / Our kids don't have passports yet. / You're right. They need to get passport photos. / Let's have their photos taken this afternoon. / What are you doing? / We're making plans for our summer vacation. / Great! I can't wait to see the pyramids.$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
