    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 3, $q$Grammar$q$, $q$Students will ask and answer “What will he do during vacation?” (“He'll probably go rafting.”).$q$, $q$What will he do during vacation? / He'll probably go rafting. / She'll probably go on a cruise. / She probably won't go on a cruise.$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
