    INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 8, $q$Unit 6 · At the Fair$q$, $q$Conversation: Our class is going to march in the school parade. / Everyone is going to dress up like a storybook character. / What will you dress up as for the parade? / I want to dress up like Peter Pan. / I have your costume ready. / Thank you. It looks great!
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Conversation$q$, $q$Students will act out the conversation that starts “Our class is going to march in the school parade.”$q$, $q$Our class is going to march in the school parade. / Everyone is going to dress up like a storybook character. / What will you dress up as for the parade? / I want to dress up like Peter Pan. / I have your costume ready. / Thank you. It looks great!$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
