    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Conversation$q$, $q$Students will act out the conversation that starts “Mom, can we make muffins?”$q$, $q$Mom, can we make muffins? / Sure, we can. We need flour, eggs, milk, butter, and sugar. / We're out of eggs. We need more milk. / Let's go grocery shopping first. / How much flour should we get? / A bag of flour will do.$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
