    INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 11, $q$Unit 8 · At the Library$q$, $q$Conversation: I have to return some books. / Do you want to come with me? / OK. I need to borrow some books. / Wait. Let me drop off these books first. / Alright. Take your time. / Excuse me. I'd like to check out these books. / Can I see your library card? / Here you are.
