    INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 13, $q$Unit 9 · Fun Experiences$q$, $q$Conversation: What did you do last summer? / We went to the Grand Canyon. / Wow! I'm jealous! / How long did you stay there? / We were there for seven days, and we did so many things. / What did you like best? / The rafting was fun.
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Conversation$q$, $q$Students will act out the conversation that starts “What did you do last summer?”$q$, $q$What did you do last summer? / We went to the Grand Canyon. / Wow! I'm jealous! / How long did you stay there? / We were there for seven days, and we did so many things. / What did you like best? / The rafting was fun.$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
