    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 3, $q$Grammar$q$, $q$Students will ask and answer “Has he ever gone camping?” (“Yes, he has. No, he hasn't.”).$q$, $q$Has he ever gone camping? / Yes, he has. No, he hasn't. / Have you ever been to a library? / Yes, I have. No, I haven't.$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
