    INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 14, $q$Unit 10 · Growing Up$q$, $q$Conversation: You're very good at skiing. / Who taught you? / My uncle taught me how to ski. / How old were you when you started skiing? / I was six years old. / Really? I wish I could ski like you. / Come on. I'll show you.
    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Conversation$q$, $q$Students will act out the conversation that starts “You're very good at skiing.”$q$, $q$You're very good at skiing. / Who taught you? / My uncle taught me how to ski. / How old were you when you started skiing? / I was six years old. / Really? I wish I could ski like you. / Come on. I'll show you.$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
