    INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Conversation$q$, $q$Students will act out the conversation that starts “What's that? That's my picture book.”$q$, $q$What's that? / That's my picture book. / This picture book looks old. / It is. I've had it since I was in kindergarten. / That's a long time. Where did you get it? / It was a birthday gift from my mom.$q$, ARRAY[]::text[], ARRAY[]::text[], 'claude');
